    private static void eq(String fn, String in, String got, String want) {
        check(want.equals(got), fn + "(\"" + in + "\") = \"" + got + "\", expected \"" + want + "\"");
    }

    private static void near(String what, double got, double want) {
        check(Math.abs(got - want) < 1e-6, what + " = " + got + ", expected " + want);
    }

    private static List<String[]> splits(String[][] rows) {
        List<String[]> out = new ArrayList<>();
        for (String[] r : rows) out.add(new String[]{r[0], r[1]});
        return out;
    }

    /** Fake search: the captured response for known keywords, an empty 200 page for anything else. */
    private static final class Fake implements MusicResolver.Search {
        final List<String> asked = new ArrayList<>();
        public JSONObject songs(String keywords) {
            asked.add(keywords);
            JSONObject hit = songs.optJSONObject(keywords);
            if (hit != null) return new JSONObject(hit.toString());
            return new JSONObject("{\"code\":200,\"result\":{\"songCount\":0,\"songs\":[]}}");
        }
    }

    private static void resolveCase(String u, String content, String[][] splitRows, boolean wantsVersion, String[] queries,
                                    String[] asked, long id, boolean confident) {
        List<String[]> s = splits(splitRows);
        check(MusicResolver.queries(content, s).equals(Arrays.asList(queries)),
                "queries for \"" + u + "\" = " + MusicResolver.queries(content, s) + ", expected " + Arrays.asList(queries));
        Fake fake = new Fake();
        MusicResolver.Pick pick;
        try {
            pick = MusicResolver.resolve(content, s, wantsVersion, fake);
        } catch (IOException e) {
            check(false, "resolve(\"" + u + "\") threw " + e);
            return;
        }
        check(fake.asked.equals(Arrays.asList(asked)), "resolve(\"" + u + "\") asked " + fake.asked + ", expected " + Arrays.asList(asked));
        if (id == 0L) {
            check(pick == null, "resolve(\"" + u + "\") should find nothing but picked " + (pick == null ? "" : pick.id + " " + pick.title));
            return;
        }
        check(pick != null && pick.id == id, "resolve(\"" + u + "\") picked " + (pick == null ? "null" : pick.id + " " + pick.title + " / " + pick.artist) + ", expected id " + id);
        if (pick != null) check(pick.confident == confident, "resolve(\"" + u + "\").confident = " + pick.confident + ", expected " + confident);
    }

    private static void errors() {
        MusicResolver.Search limited = k -> new JSONObject("{\"code\":406,\"msg\":\"操作频繁\"}");
        List<String[]> s = splits(new String[][]{{"薛之谦", "你还要我怎样"}, {"", "薛之谦的你还要我怎样"}});
        try {
            MusicResolver.resolve("薛之谦的你还要我怎样", s, false, limited);
            check(false, "code 406 should throw IOException(rate_limited)");
        } catch (IOException e) {
            check("rate_limited".equals(e.getMessage()), "code 406 message = " + e.getMessage() + ", expected rate_limited");
        }
        MusicResolver.Search broken = k -> new JSONObject("{\"code\":500}");
        try {
            MusicResolver.resolve("薛之谦的你还要我怎样", s, false, broken);
            check(false, "code 500 should throw IOException(search_failed)");
        } catch (IOException e) {
            check("search_failed".equals(e.getMessage()), "code 500 message = " + e.getMessage() + ", expected search_failed");
        }
        // first query gives only a non-confident candidate, the second query fails: keep the candidate
        final int[] calls = {0};
        MusicResolver.Search flaky = k -> {
            if (calls[0]++ == 0) return new JSONObject("{\"code\":200,\"result\":{\"songs\":[{\"id\":42,\"name\":\"你还要我怎样\",\"artists\":[{\"name\":\"别人\"}],\"album\":{\"name\":\"x\",\"size\":1},\"fee\":8}]}}");
            throw new IOException("network");
        };
        try {
            MusicResolver.Pick p = MusicResolver.resolve("薛之谦的你还要我怎样", s, false, flaky);
            check(p != null && p.id == 42 && !p.confident, "later failure keeps the earlier non-confident pick");
        } catch (IOException e) {
            check(false, "later failure after a candidate should not throw: " + e);
        }
        // a 200 page without result/songs is just empty
        try {
            MusicResolver.Pick p = MusicResolver.resolve("你还要我怎样", splits(new String[][]{{"", "你还要我怎样"}}), false, k -> new JSONObject("{\"code\":200}"));
            check(p == null, "200 without songs gives null");
        } catch (IOException e) {
            check(false, "200 without songs should not throw: " + e);
        }
        // pick fields: artist credits joined with '/', album name, score > 0
        try {
            MusicResolver.Pick p = MusicResolver.resolve("周杰伦的我的地盘", splits(new String[][]{{"周杰伦", "我的地盘"}, {"", "周杰伦的我的地盘"}}), false, new Fake());
            check(p != null && "我的地盘".equals(p.title) && "周杰伦".equals(p.artist) && "七里香".equals(p.album) && p.score > 0,
                    "pick fields title/artist/album/score");
        } catch (IOException e) {
            check(false, "fields case threw " + e);
        }
    }

